"use strict";(self.webpackChunkdocs_site=self.webpackChunkdocs_site||[]).push([["753"],{1038(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"full-scale","label":"Full Scale","banner":"unmaintained","badge":true,"noIndex":false,"className":"docs-version-full-scale","isLast":false,"docsSidebars":{"overviewSidebar":[{"type":"link","href":"/full-scale/overview/","label":"Overview","docId":"overview/index","unlisted":false}],"dataSidebar":[{"type":"link","href":"/full-scale/data/","label":"Layer 1 \u2014 Data","docId":"data/index","unlisted":false}],"componentsSidebar":[{"type":"link","href":"/full-scale/components/","label":"Layer 2 \u2014 Components","docId":"components/index","unlisted":false}],"businessLogicSidebar":[{"type":"link","href":"/full-scale/business-logic/","label":"Layer 3 \u2014 Business Logic","docId":"business-logic/index","unlisted":false}],"apiSidebar":[{"type":"link","href":"/full-scale/api/","label":"Overview","docId":"api/index","unlisted":false}],"clientsSidebar":[{"type":"link","href":"/full-scale/clients/","label":"Layer 5 \u2014 Clients","docId":"clients/index","unlisted":false}]},"docs":{"api/index":{"id":"api/index","title":"Overview","description":"The stable, public contract \u2014 operations, reads, and events \u2014 that clients consume. Implemented as per-domain microservices behind load balancers; the surface a tenant sees reflects its variant (which endpoints exist) plus its extensions (additional or overridden behavior).","sidebar":"apiSidebar"},"business-logic/index":{"id":"business-logic/index","title":"Layer 3 \u2014 Business Logic","description":"The opinionated rule sets that turn permissive components into a usable product, organized as variant templates per vertical (CPG manufacturing, dropshipping, distribution, \u2026). Each variant ships with a baseline template every tenant on that variant uses, and tenants can optionally layer their own extensions on top \u2014 overriding rules, adding validations, customizing workflows \u2014 without touching the variant or other tenants.","sidebar":"businessLogicSidebar"},"clients/index":{"id":"clients/index","title":"Layer 5 \u2014 Clients","description":"Visualization and interaction surfaces: web app, mobile app, desktop app, CLI, AI agents (MCP, A2A, \u2026), and partner integrations (Slack, EDI, accounting, BI, \u2026). All clients consume the same public API \u2014 no privileged path to lower layers \u2014 and the architecture treats first-party and third-party clients identically.","sidebar":"clientsSidebar"},"components/index":{"id":"components/index","title":"Layer 2 \u2014 Components","description":"Mechanically permissive primitives, exposed as stateless, org-agnostic microservices \u2014 one per domain (Platform, Purchase Order, Work Order, Sales Order, Materials Inventory, Finished Goods Inventory). Each scales horizontally with multiple instances behind a load balancer, and operates on whatever connection Layer 1 hands it \u2014 a component has no notion of which tenant it serves beyond the connection itself.","sidebar":"componentsSidebar"},"data/index":{"id":"data/index","title":"Layer 1 \u2014 Data","description":"Where state lives. One database per organization, distributed across multiple Postgres instances \u2014 smaller orgs share an instance, larger orgs run on dedicated ones \u2014 plus a separate platform instance holding the tenant catalog and cross-tenant data (users, auth, membership). Every instance is replicated (primary + replica) for reliability.","sidebar":"dataSidebar"},"overview/index":{"id":"overview/index","title":"Overview","description":"Pharus is a platform. This document describes its architecture as a stack of layers, each with a clear responsibility and contract. The intent is to keep the layers genuinely separate so the platform can support multiple use cases (CPG manufacturing, dropshipping, distribution, etc.) and allow tenant-defined customization, without forking the foundation each time.","sidebar":"overviewSidebar"}}}}')}}]);